import Foundation

struct IntrinsicMetric {
    let paddingHorizontal: Double
    let contentWidth: Double

    var totalWidth: Double {
        contentWidth + (paddingHorizontal * 2)
    }
}

let metric = IntrinsicMetric(paddingHorizontal: 16.0, contentWidth: 100.0)
print("Width: \(metric.totalWidth)")

import Foundation

class SimpleLayoutSimulator {
    var isDirty = false
    var passes = 0

    func requestLayout() {
        isDirty = true
    }

    func performLayout() {
        if isDirty {
            passes += 1
            isDirty = false
        }
    }
}

let sim = SimpleLayoutSimulator()
sim.requestLayout()
sim.requestLayout()
sim.performLayout()
print("Passes: \(sim.passes), Dirty: \(sim.isDirty)")

