import Foundation

class LayoutBatchTracker {
    var requestCount = 0
    var executedPasses = 0

    func invalidate() {
        requestCount += 1
    }

    func flush() {
        if requestCount > 0 {
            executedPasses += 1
            requestCount = 0
        }
    }
}

let tracker = LayoutBatchTracker()
tracker.invalidate()
tracker.invalidate()
tracker.invalidate()
tracker.flush()
print("Executed: \(tracker.executedPasses)")

import Foundation

struct SubviewPositioner {
    var subviewCount: Int
    var itemHeight: Double

    func totalContentHeight() -> Double {
        Double(subviewCount) * itemHeight
    }
}

let positioner = SubviewPositioner(subviewCount: 4, itemHeight: 30.0)
