import Foundation

class UpdatePhaseRecorder {
    var sequence: [String] = []

    func recordConstraints() {
        sequence.append("constraints")
    }

    func recordLayout() {
        sequence.append("layout")
    }

    func recordDraw() {
        sequence.append("draw")
    }
}

let recorder = UpdatePhaseRecorder()
recorder.recordConstraints()
recorder.recordLayout()
recorder.recordDraw()
print(recorder.sequence.joined(separator: "->"))

import Foundation

class AnimationSimulator {
    var constant: Double = 50.0
    var didAnimate = false

    func updateConstant(to newConstant: Double, animate: Bool) {
        constant = newConstant
        didAnimate = animate
    }
}

let sim = AnimationSimulator()
sim.updateConstant(to: 120.0, animate: true)
print("Constant: \(sim.constant), Animated: \(sim.didAnimate)")

import Foundation

struct MarginCalculator {
    let leftMargin: Double
    let rightMargin: Double
    let spacing: Double
    let columns: Int
    let colWidth: Double

    var totalWidth: Double {
        leftMargin + rightMargin + (Double(columns) * colWidth) + (Double(columns - 1) * spacing)
    }
}

let calc = MarginCalculator(leftMargin: 10.0, rightMargin: 10.0, spacing: 8.0, columns: 2, colWidth: 100.0)
print("Span: \(calc.totalWidth)")

